// src/modules/work/workers/worker.routes.ts
import { FastifyPluginAsync } from 'fastify';
import { workerService } from './worker.service';
import {
  createWorkerSchema,
  updateWorkerSchema,
  workerIdParamsSchema,
  listWorkersQuerySchema,
} from './worker.schemas';
import { z } from 'zod';

const workerRoutes: FastifyPluginAsync = async (fastify) => {
  /**
   * POST /work/workers
   * Criar perfil de worker para o usuário autenticado
   */
  fastify.post<{
    Body: z.infer<typeof createWorkerSchema>;
  }>('/', {
    preHandler: fastify.requirePermission(['work:worker:create']),
  }, async (req, reply) => {
    // Validação manual com Zod
    const body = createWorkerSchema.parse(req.body);
    const tenantId = req.tenant!.id;
    const userId = req.user!.id;

    const worker = await workerService.createWorker(tenantId, userId, body);

    return reply.status(201).send(worker);
  });

  /**
   * GET /work/workers/me
   * Buscar meu perfil de worker
   */
  fastify.get('/me', {
    preHandler: fastify.requirePermission(['work:worker:read']),
  }, async (req, reply) => {
    const tenantId = req.tenant!.id;
    const userId = req.user!.id;

    const worker = await workerService.getByUserId(tenantId, userId);

    if (!worker) {
      return reply.notFound('Worker profile not found');
    }

    return worker;
  });

  /**
   * GET /work/workers
   * Listar workers com filtros
   */
  fastify.get<{
    Querystring: z.infer<typeof listWorkersQuerySchema>;
  }>('/', {
    preHandler: fastify.requirePermission(['work:worker:read']),
  }, async (req) => {
    // Validação manual com Zod
    const query = listWorkersQuerySchema.parse(req.query);
    const tenantId = req.tenant!.id;
    const result = await workerService.listWorkers(tenantId, query);
    return result;
  });

  /**
   * GET /work/workers/:workerId
   * Buscar worker por ID
   */
  fastify.get<{
    Params: z.infer<typeof workerIdParamsSchema>;
  }>('/:workerId', {
    preHandler: fastify.requirePermission(['work:worker:read']),
  }, async (req, reply) => {
    // Validação manual com Zod
    const params = workerIdParamsSchema.parse(req.params);
    const tenantId = req.tenant!.id;
    const { workerId } = params;

    const worker = await workerService.getById(tenantId, workerId);

    if (!worker) {
      return reply.notFound('Worker not found');
    }

    return worker;
  });

  /**
   * PATCH /work/workers/:workerId
   * Atualizar worker
   */
  fastify.patch<{
    Params: z.infer<typeof workerIdParamsSchema>;
    Body: z.infer<typeof updateWorkerSchema>;
  }>('/:workerId', {
    preHandler: fastify.requirePermission(['work:worker:update']),
  }, async (req) => {
    // Validação manual com Zod
    const params = workerIdParamsSchema.parse(req.params);
    const body = updateWorkerSchema.parse(req.body);
    const tenantId = req.tenant!.id;
    const { workerId } = params;

    // 🔴 LOGGING: Log payload antes de processar para diagnóstico
    fastify.log.info({
      workerId,
      tenantId,
      hasAvailability: !!body.availability,
      availabilityType: typeof body.availability,
      availabilityIsNull: body.availability === null,
      availabilityIsUndefined: body.availability === undefined,
    }, '[WorkerRoutes] PATCH /work/workers/:workerId - Payload recebido');

    const worker = await workerService.updateWorker(tenantId, workerId, body);
    return worker;
  });
};

export default workerRoutes;
